/* Put an earlier published version of a website live again (Website settings › Backups & Versions › Published versions), run after parts 130 and 180. A new server only function `rollback_site_release(install, creator, release)` writes that release back into the live rows in one transaction, under the same per creator lock Publish takes (part 130): the live theme settings, every page's live sections (a page the release did not have is removed) and every theme file from `theme_file_blobs` (a file the release did not have is removed), each draft cleared, this website switched live as Publish switches it, then the same manifest kept as a new release marked `restored_from` and the website pointed at it, its `rev` counted up so a release still being written by an earlier Publish cannot take the pointer back. Refuses a release of another website or creator, one it cannot read, and one with a file whose text is missing, changing nothing. Adds `site_releases.restored_from`. Only the service role can call it. Changes no existing row. Needs the theme tables and part 180; without them it skips itself with a notice. Until it runs, Published versions does not show and nothing else changes. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.site_releases') IS NULL OR to_regclass('public.site_live_releases') IS NULL OR to_regclass('public.theme_file_blobs') IS NULL OR to_regclass('public.store_theme_installs') IS NULL OR to_regclass('public.store_theme_pages') IS NULL OR to_regclass('public.store_theme_settings') IS NULL OR to_regclass('public.store_theme_custom_files') IS NULL THEN RAISE NOTICE 'part 188: the theme tables or part 180 are not there yet, rollback is skipped. Run them, then this part again.'; RETURN; END IF; ALTER TABLE public.site_releases ADD COLUMN IF NOT EXISTS restored_from uuid; ALTER TABLE public.store_theme_installs ADD COLUMN IF NOT EXISTS published_at timestamptz; ALTER TABLE public.store_theme_custom_files ADD COLUMN IF NOT EXISTS draft_content text; EXECUTE $fn$CREATE OR REPLACE FUNCTION public.rollback_site_release(p_install uuid, p_creator uuid, p_release uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $body$ DECLARE v_from public.site_releases%ROWTYPE; v_m jsonb; v_missing integer; v_files jsonb; v_was jsonb; v_settings jsonb; v_new uuid; BEGIN IF NOT EXISTS (SELECT 1 FROM public.store_theme_installs WHERE id = p_install AND creator_id = p_creator) THEN RAISE EXCEPTION 'rollback: this website is not this creator''s' USING ERRCODE = 'P0002'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('storelib-publish:' || p_creator::text, 0)); SELECT * INTO v_from FROM public.site_releases WHERE id = p_release AND install_id = p_install AND creator_id = p_creator; IF NOT FOUND THEN RAISE EXCEPTION 'rollback: no such release of this website' USING ERRCODE = 'P0002'; END IF; v_m := v_from.manifest; IF (v_m->>'v') IS DISTINCT FROM '1' OR jsonb_typeof(v_m->'files') IS DISTINCT FROM 'array' OR jsonb_typeof(v_m->'pages') IS DISTINCT FROM 'array' OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_m->'pages') p WHERE jsonb_typeof(p->'page_key') IS DISTINCT FROM 'string') OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_m->'files') f WHERE jsonb_typeof(f->'path') IS DISTINCT FROM 'string' OR jsonb_typeof(f->'sha256') IS DISTINCT FROM 'string') THEN RAISE EXCEPTION 'rollback: the release cannot be read' USING ERRCODE = '22023'; END IF; SELECT count(*) INTO v_missing FROM jsonb_array_elements(v_m->'files') f WHERE NOT EXISTS (SELECT 1 FROM public.theme_file_blobs b WHERE b.sha256 = f->>'sha256'); IF v_missing > 0 THEN RAISE EXCEPTION 'rollback: % files of the release are missing', v_missing USING ERRCODE = '22023'; END IF; SELECT COALESCE(jsonb_agg(jsonb_build_object('path', f->>'path', 'content', b.content)), '[]'::jsonb) INTO v_files FROM jsonb_array_elements(v_m->'files') f JOIN public.theme_file_blobs b ON b.sha256 = f->>'sha256' LEFT JOIN public.store_theme_custom_files c ON c.install_id = p_install AND c.path = f->>'path' WHERE c.content IS DISTINCT FROM b.content; IF jsonb_typeof(v_m->'settings') = 'object' THEN INSERT INTO public.store_theme_settings (install_id, settings, draft_settings) VALUES (p_install, v_m->'settings', NULL) ON CONFLICT (install_id) DO UPDATE SET settings = EXCLUDED.settings, draft_settings = NULL; ELSE UPDATE public.store_theme_settings SET settings = '{}'::jsonb, draft_settings = NULL WHERE install_id = p_install; END IF; DELETE FROM public.store_theme_pages t WHERE t.install_id = p_install AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_m->'pages') p WHERE p->>'page_key' = t.page_key); INSERT INTO public.store_theme_pages (install_id, page_key, sections, draft_sections) SELECT DISTINCT ON (p->>'page_key') p_install, p->>'page_key', COALESCE(NULLIF(p->'sections', 'null'::jsonb), '[]'::jsonb), NULL FROM jsonb_array_elements(v_m->'pages') p ORDER BY p->>'page_key' ON CONFLICT (install_id, page_key) DO UPDATE SET sections = EXCLUDED.sections, draft_sections = NULL; DELETE FROM public.store_theme_custom_files c WHERE c.install_id = p_install AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_m->'files') f WHERE f->>'path' = c.path); INSERT INTO public.store_theme_custom_files (install_id, path, content, draft_content) SELECT DISTINCT ON (f->>'path') p_install, f->>'path', b.content, NULL FROM jsonb_array_elements(v_m->'files') f JOIN public.theme_file_blobs b ON b.sha256 = f->>'sha256' ORDER BY f->>'path' ON CONFLICT (install_id, path) DO UPDATE SET content = EXCLUDED.content, draft_content = NULL; WITH down AS (UPDATE public.store_theme_installs SET status = 'unpublished' WHERE creator_id = p_creator AND status = 'published' AND id <> p_install RETURNING id) SELECT COALESCE(jsonb_agg(id), '[]'::jsonb) INTO v_was FROM down; UPDATE public.store_theme_installs SET status = 'published', published_at = now() WHERE id = p_install; SELECT settings INTO v_settings FROM public.store_theme_settings WHERE install_id = p_install; INSERT INTO public.site_releases (creator_id, install_id, manifest, file_count, total_bytes, restored_from) VALUES (p_creator, p_install, jsonb_set(v_m, '{settings}', COALESCE(v_settings, 'null'::jsonb)), v_from.file_count, v_from.total_bytes, p_release) RETURNING id INTO v_new; INSERT INTO public.site_live_releases (install_id, creator_id, release_id, rev, updated_at) VALUES (p_install, p_creator, v_new, 1, now()) ON CONFLICT (install_id) DO UPDATE SET release_id = EXCLUDED.release_id, creator_id = EXCLUDED.creator_id, rev = public.site_live_releases.rev + 1, updated_at = now(); RETURN jsonb_build_object('release_id', v_new, 'was_live', v_was, 'files', v_files); END $body$$fn$; REVOKE ALL ON FUNCTION public.rollback_site_release(uuid, uuid, uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.rollback_site_release(uuid, uuid, uuid) TO service_role; END $do$;
notify pgrst, 'reload schema';
